export function getVerberInstruction(lang = "da") {
    if (!lang || lang === "da") return "";
    return verberSaetningsbyggerData[lang]?.instruction || verberSaetningsbyggerData["en"]?.instruction || "";
}

export function getVerberCategoryQuestion(catTitle, lang = "da") {
    if (!lang || lang === "da" || !catTitle) return "";
    const cleanTitle = catTitle.trim();
    return verberSaetningsbyggerData[lang]?.categories?.[cleanTitle] ||
           verberSaetningsbyggerData["en"]?.categories?.[cleanTitle] || "";
}

export function getVerberContextTranslation(contextText, lang = "da") {
    if (!lang || lang === "da" || !contextText) return "";
    const clean = contextText.trim();
    return verberSaetningsbyggerData[lang]?.contexts?.[clean] ||
           verberSaetningsbyggerData["en"]?.contexts?.[clean] || "";
}

